    {active==="signup"&&<section className="dp-form-layout"><div><span className="dp-eyebrow">CREATE YOUR ACCOUNT</span><h2>One identity. <em>Many possibilities.</em></h2><p>Create your personal MONK account first. You can then create or join authorized workspaces.</p></div><form className="dp-form" onSubmit={e=>{e.preventDefault();go("role");}}><div className="dp-two-fields"><Field label="First name"/><Field label="Last name"/></div><Field label="Email address" type="email"/><Field label="Mobile number" type="tel"/><Field label="Create password" type="password"/><Field label="Confirm password" type="password"/><label className="dp-check"><input type="checkbox"/> I agree to the Terms and Privacy Policy.</label><Button>Create account <ArrowRight size={15}/></Button></form></section>}
    {active==="forgot"&&<section className="dp-auth-wrap"><div className="dp-auth-aside"><Mark/><span>ACCOUNT RECOVERY</span><h2>Back to your <em>workspace.</em></h2><p>Use the email address connected to your MONK account.</p></div><form className="dp-form dp-auth-card" onSubmit={e=>{e.preventDefault();submit("Password reset request preview only. No email was sent.");}}><h2>Forgot password?</h2><Field label="Email address" type="email"/><Button>Send reset link <ArrowRight size={15}/></Button><button type="button" className="dp-link" onClick={()=>go("login")}>Back to login</button></form></section>}
    {active==="role"&&<section className="dp-section"><div className="dp-section-heading"><span>CHOOSE YOUR ROLE</span><h2>Which experience is <em>yours?</em></h2><p>Your role determines the next setup steps and workspace permissions.</p></div><div className="dp-role-grid">{roles.map((r,i)=><button className={role===r?"chosen":""} onClick={()=>setRole(r)}><span className="dp-icon pink">{[<GraduationCap/>,<Users/>,<BookOpen/>,<Building2/>,<BriefcaseBusiness/>,<Users/>][i]}</span><b>{r}</b><small>{["Learning and campus life","Follow a linked learner","Classes and academic work","Manage an institution","Run a business workspace","Work with an organization"][i]}</small><CheckCircle2/></button>)}</div><div className="dp-center"><Button onClick={()=>go(role==="Student"?"student-enroll":role.startsWith("Parent")?"parent":role==="Teacher"?"teacher":role.includes("Admin")?"institution-register":role==="Business Owner"?"business-setup":"team")}>Continue as {role} <ArrowRight size={15}/></Button></div></section>}
    {active==="institution-register"&&<section className="dp-form-layout"><div><span className="dp-eyebrow">INSTITUTION ONBOARDING</span><h2>Register your <em>institution.</em></h2><p>Submit official details for review. Verification is based on evidence and authoritative records.</p><div className="dp-steps"><span>01 Details</span><span>02 Documents</span><span>03 Review</span><span>04 Activation</span></div></div><form className="dp-form" onSubmit={e=>{e.preventDefault();go("institution-review");}}><Field label="Legal institution name" placeholder="Official registered name"/><label className="dp-field"><span>Institution type</span><select><option>College / University</option><option>Polytechnic</option><option>School</option><option>Private coaching / Training institute</option></select></label><div className="dp-two-fields"><Field label="Official email" type="email"/><Field label="Contact number" type="tel"/></div><Field label="Affiliation / Board / Regulator"/><div className="dp-two-fields"><Field label="State"/><Field label="District"/></div><Field label="Official website (optional)"/><label className="dp-field"><span>Upload registration / affiliation documents</span><input type="file" multiple/></label><label className="dp-check"><input type="checkbox"/> I confirm that I am authorized to submit this application.</label><Button>Submit for verification <ArrowRight size={15}/></Button></form></section>}
    {active==="institution-review"&&<section className="dp-section"><div className="dp-section-heading"><span>VERIFICATION TRACKER</span><h2>Application <em>progress.</em></h2></div><Panel title="Institution verification · Application preview"><div className="dp-progress"><div><CheckCircle2/><b>Application submitted</b><small>Details and documents received</small></div><div><span className="dp-pending">02</span><b>Document review</b><small>Awaiting authorized reviewer</small></div><div><span className="dp-pending">03</span><b>Decision</b><small>Approval or request for changes</small></div></div><p className="dp-muted">A verified badge appears only after checks are completed and recorded.</p></Panel></section>}
