    {active==="institution-directory"&&<section className="dp-section"><div className="dp-section-heading"><span>VERIFIED INSTITUTION DIRECTORY</span><h2>Explore places to <em>learn.</em></h2><p>Directory cards distinguish MONK verification from official affiliation or accreditation claims.</p></div><div className="dp-two-cards"><article><span className="dp-status-pill">MONK verified</span><h3>Government Polytechnic Muzaffarpur</h3><p>Polytechnic · Bihar · Mechanical, Civil, Electrical and other programmes.</p><Button kind="light" onClick={()=>go("institution-detail")}>View institution <ArrowRight size={14}/></Button></article><article><span className="dp-status-pill">MONK verified</span><h3>Northside Coaching Institute</h3><p>Coaching / Training · Muzaffarpur · Competitive exam preparation.</p><Button kind="light" onClick={()=>go("institution-detail")}>View institution <ArrowRight size={14}/></Button></article></div></section>}
    {active==="institution-detail"&&<section className="dp-section"><div className="dp-profile-head"><div className="dp-avatar business"><Building2/></div><div><span className="dp-eyebrow">INSTITUTION PROFILE</span><h2>Government Polytechnic Muzaffarpur</h2><p>Polytechnic · Muzaffarpur, Bihar · MONK verification status shown separately from external recognition.</p></div><span className="dp-status-pill">MONK verified</span></div><div className="dp-three"><article><h3>Institution overview</h3><p>Official name, address, website, contact details, establishment and verification record.</p></article><article><h3>Programmes</h3><p>Course level, branch, duration, eligibility, intake and admission route.</p></article><article><h3>Campus information</h3><p>Departments, facilities, notices, contact and verified links.</p></article></div><div className="dp-center"><Button onClick={()=>go("student-enroll")}>Apply or link admission <ArrowRight size={14}/></Button></div></section>}
